    std::string version;
    int count;
    if (!(in >> version >> count) || version != "EV1" || count < 0 ||
        count > 8) {
        return false;
    }
    std::vector<int> candidate;
    for (int i = 0; i < count; ++i) {
        int x;
        if (!(in >> x) || x < 0 || x > 100) {
            return false;
        }
        candidate.push_back(x);
    }
